impl ThemeColors {
    /// `bg`: Convenience alias of md-sys-color-surface.
    pub const fn bg(&self) -> Color32 {
        self.surface
    }

    /// `fg`: Convenience alias of md-sys-color-on-surface: body text.
    pub const fn fg(&self) -> Color32 {
        self.on_surface
    }

    /// `bg-elevated`: Convenience alias of surface-container-low: raised cards.
    pub const fn bg_elevated(&self) -> Color32 {
        self.surface_container_low
    }

    /// `border`: Convenience alias of md-sys-color-outline.
    pub const fn border(&self) -> Color32 {
        self.outline
    }

    /// `border-decor`: Convenience alias of md-sys-color-outline-variant: decorative hairlines only.
    pub const fn border_decor(&self) -> Color32 {
        self.outline_variant
    }

    /// `accent`: Convenience alias of md-sys-color-tertiary, the Bronze accent.
    pub const fn accent(&self) -> Color32 {
        self.tertiary
    }

    /// `text-body`: Body text colour, alias of md-sys-color-on-surface: 13.1:1 on Cream and on the dark surface.
    pub const fn text_body(&self) -> Color32 {
        self.on_surface
    }

    /// `text-muted`: Muted text: ledes, captions, hints, table headers. Alias of on-surface-variant, 7.6:1 on Cream.
    pub const fn text_muted(&self) -> Color32 {
        self.on_surface_variant
    }

    /// `text-display`: Display and headline colour, alias of md-sys-color-primary: Forest on Cream 10.1:1, forest-80 on the dark surface 8.6:1. Lowest across the six themes: 6.4:1 on md-sys-color-surface.
    pub const fn text_display(&self) -> Color32 {
        self.primary
    }
}
